/* Stages 3-4 lessons */
export const LESSONS_B={
'boolean-expr':{intro:'Every decision starts with a yes/no question. Boolean expressions answer true or false — the electricity of logic.',question:'How does a bouncer decide in one glance?',analogy:'Bouncer checklist: age ≥ 18? AND on list? NOT banned? Each is true/false; combined verdict opens the rope.',analogyFail:'Where it breaks: bouncers bend rules. Booleans never bend — exactly true or false, no “maybe”.',explain:['<b>Comparisons</b>: == != < <= > >=. Result is boolean. 5 > 3 → true.','<b>Logic</b>: && both, || either, ! flips. Precedence: ! → comparisons → && → ||.','<b>Strings</b>: use equals(), never ==. <b>Short-circuit</b>: && stops at first false.'],code:`int age = 20;\nboolean canVote = age >= 18;\nboolean vip = age >= 18 && age < 65;\nboolean deny = !(age >= 18);\nSystem.out.println(canVote + " " + vip + " " + deny);`,codeNotes:['>= asks a true/false question.','&& needs both sides true.','! flips the answer.'],output:'true true false',why:'20≥18 is true, 20<65 is true so vip is true; deny flips true to false.',sim:{kind:'cond',label:'Bouncer test: try ages.',fields:[{v:'20'}]},mistakes:[{bad:'if (age = 18)',why:'= stores, not asks.',fix:'if (age == 18)'},{bad:'"a" == "a" for text',why:'Compares houses.',fix:'s.equals("a")'},{bad:'true && false expected true',why:'AND needs both.',fix:'Truth-table it: T&&F = F.'}],practices:[{title:'Bouncer logic',task:'Write canEnter = age≥18 && hasTicket.',hint:'Both must hold.',sol:'boolean canEnter = age >= 18 && hasTicket;'},{title:'De Morgan',task:'Negate (a && b) without &&.',hint:'!(a&&b) = !a || !b.',sol:'boolean r = !a || !b;'}],quiz:[{id:'q1',prompt:'5 > 3 && 2 > 9 gives?',options:[{t:'false',ok:true},{t:'true'},{t:'maybe'},{t:'error'}],explain:'T && F = F.'},{id:'q2',prompt:'!true || false = ?',options:[{t:'false',ok:true},{t:'true'},{t:'error'},{t:'null'}],explain:'!true=F, F||F=F.'},{id:'q3',prompt:'Compare strings with?',options:[{t:'.equals()',ok:true},{t:'=='},{t:'='},{t:'~~~'}],explain:'Content compare.'}],takeaways:['Booleans are exactly true/false.','&& both, || either, ! flips.','Use equals for text.'],recall:'What is short-circuit evaluation?',todo:'Write 3 boolean rules for a game you like.',anim:{title:'Bouncer checklist',steps:[{caption:'Q1: age ≥ 18? → true.',html:'<div class="viz"><div class="varbox"><div class="nm">age ≥ 18</div><div class="vl">true</div></div></div>'},{caption:'Q2: has ticket? → true.',html:'<div class="viz"><div class="varbox"><div class="nm">ticket</div><div class="vl">true</div></div></div>'},{caption:'AND: both true → enter ✓.',html:'<div class="pipe"><div class="box">true && true</div><span class="arr">→</span><div class="box"><b>enter ✓</b></div></div>'}]}},
'if-else':{intro:'if lets programs choose. One question, two futures — the code picks the true path and skips the other.',question:'What do traffic lights do that a straight road cannot?',analogy:'Fork in a trek path. Sign asks “rain?” — left shelter, else viewpoint. You walk exactly one branch, never both.',analogyFail:'Where it breaks: trekkers can turn back. Code cannot un-run a branch — choice is one-way per run.',explain:['<b>if (cond) { } else if { } else { }</b>. First true branch runs; rest skipped.','<b>else</b> catches everything left. Chain from specific to general.','Beware <b>= vs ==</b> and missing braces with two lines.'],code:`int marks = 82;\nif (marks >= 90) {\n  System.out.println("A");\n} else if (marks >= 75) {\n  System.out.println("B");\n} else {\n  System.out.println("Keep going");\n}`,codeNotes:['82 fails ≥90, passes ≥75 → B.','Only one branch prints.','else is the safety net.'],output:'B',why:'First true condition wins; later branches skipped entirely.',sim:{kind:'cond',label:'Try marks; watch the branch.',fields:[{v:'82'}]},mistakes:[{bad:'if (marks = 90)',why:'Assignment, always truthy-ish (actually int error).',fix:'if (marks == 90)'},{bad:'Two ifs when else-if needed',why:'Both can fire.',fix:'Chain else-if for exclusive choices.'},{bad:'if (x > 5); { ... }',why:'Stray ; ends the if!',fix:'Remove the semicolon.'}],practices:[{title:'Grade it',task:'marks=45 → what prints? Trace.',hint:'Falls to else.',sol:'Keep going.'},{title:'Fizz-ish',task:'Print “even” if n%2==0 else “odd”.',hint:'One if-else.',sol:'if (n % 2 == 0) ... else ...'}],quiz:[{id:'q1',prompt:'marks=95 prints?',options:[{t:'A',ok:true},{t:'B'},{t:'Both A and B'},{t:'Nothing'}],explain:'First true wins.'},{id:'q2',prompt:'How many branches run per if-chain?',options:[{t:'At most one',ok:true},{t:'All true ones'},{t:'Always two'},{t:'Zero or all'}],explain:'Exclusive choice.'},{id:'q3',prompt:'if (x > 5); is bad because…',options:[{t:'Semicolon ends if early',ok:true},{t:'x is small'},{t:'Brackets missing'},{t:'Java hates x'}],explain:'Empty statement swallows the check.'}],takeaways:['First true branch runs, rest skipped.','Order specific → general.','No stray semicolon after if.'],recall:'Why order conditions specific-first?',todo:'Write rain-or-shine planner with if-else.',anim:{title:'Fork path',steps:[{caption:'Ask: marks ≥ 90? No.',html:'<div class="pipe"><div class="box">≥90? ❌</div></div>'},{caption:'Ask: ≥ 75? Yes → B.',html:'<div class="pipe"><div class="box">≥75? ✓</div><span class="arr">→</span><div class="box"><b>B</b></div></div>'},{caption:'Other branches skipped.',html:'<div class="pipe"><div class="box">else ignored</div></div>'}]}},
'nested-cond':{intro:'Real choices stack: inside “it rains” sits “have umbrella?”. Nest carefully — or flatten with &&.',question:'When is a box inside a box clearer than two boxes side by side?',analogy:'Russian dolls: outer “weekend?” contains inner “sunny?”. Two levels fine; five dolls confuse — flatten into one checklist.',analogyFail:'Where it breaks: dolls always fit. Nested ifs hide paths exponentially — 3 levels = 8 paths to test.',explain:['<b>Nesting</b> = if inside if. Inner runs only if outer true.','Flatten when possible: <b>if (a && b)</b> beats two levels. <b>Guard clauses</b> return early.','Trace with a table: list outer/inner combos.'],code:`boolean weekend = true;\nboolean sunny = false;\nif (weekend) {\n  if (sunny) System.out.println("Picnic");\n  else System.out.println("Museum");\n} else {\n  System.out.println("Work");\n}`,codeNotes:['Outer true → enter.','Inner false → Museum.','Else pairs with nearest if — use braces.'],output:'Museum',why:'Weekend true, sunny false → inner else.',sim:{kind:'cond',label:'Weekend logic: try values.',fields:[{v:'18'}]},mistakes:[{bad:'Dangling else confusion',why:'else binds nearest if.',fix:'Always brace nested ifs.'},{bad:'5-deep nesting',why:'Untestable paths.',fix:'Flatten with && or early return.'},{bad:'Checking inner before outer set',why:'Null/empty outer crashes.',fix:'Outer validates first.'}],practices:[{title:'Flatten it',task:'Flatten: if (a) { if (b) { go(); } }',hint:'One &&.',sol:'if (a && b) { go(); }'},{title:'Count paths',task:'2 nested ifs = how many paths?',hint:'2 × 2.',sol:'4: TT, TF, FT, FF (outer false skips inner).'}],quiz:[{id:'q1',prompt:'weekend=F prints?',options:[{t:'Work',ok:true},{t:'Picnic'},{t:'Museum'},{t:'Nothing'}],explain:'Outer false → outer else.'},{id:'q2',prompt:'Best fix for deep nesting?',options:[{t:'Flatten with && / early return',ok:true},{t:'More nesting'},{t:'Delete else'},{t:'Add semicolons'}],explain:'Fewer paths, clearer.'},{id:'q3',prompt:'else pairs with…',options:[{t:'Nearest if',ok:true},{t:'First if'},{t:'Random if'},{t:'No if'}],explain:'Brace to be explicit.'}],takeaways:['Nesting = choice inside choice.','Flatten with && when you can.','Brace everything.'],recall:'When is nesting justified vs &&?',todo:'Rewrite one nested if with &&.',anim:{title:'Dolls',steps:[{caption:'Outer doll: weekend? yes.',html:'<div class="pipe"><div class="box"><b>weekend ✓</b> open</div></div>'},{caption:'Inner doll: sunny? no.',html:'<div class="pipe"><div class="box"><b>sunny ❌</b> → museum</div></div>'},{caption:'Flattened: weekend && sunny?',html:'<div class="pipe"><div class="box">weekend && sunny</div></div>'}]}},
'switch':{intro:'switch is a mail sorter: one value, many labeled slots. Cleaner than 6 else-ifs when comparing one thing to many constants.',question:'Why do post offices sort by pincode, not by reading each letter fully?',analogy:'Pincode sorter: look at one code, slide into exactly one slot. Default slot catches unknown codes. Forgetting break = letter slides into next slot too (fall-through).',analogyFail:'Where it breaks: sorter handles labels only (numbers, strings, enums). Ranges like “> 90” need if-else.',explain:['<b>switch (day) { case 1: ... break; default: ... }</b>. <b>break</b> stops fall-through.','Modern <b>arrow form</b>: case 1 -> "Mon"; no break needed, can be an expression.','Use for fixed choices (days, grades letters, menu numbers). Use if for ranges.'],code:`int day = 3;\nString name = switch (day) {\n  case 1 -> "Monday";\n  case 2 -> "Tuesday";\n  case 3 -> "Wednesday";\n  default -> "Unknown";\n};\nSystem.out.println(name);`,codeNotes:['day=3 matches one case.','Arrow needs no break.','default catches the rest.'],output:'Wednesday',why:'Exact match on 3; expression yields the string.',sim:{kind:'cond',label:'Day sorter: try 1-7.',fields:[{v:'3'}]},mistakes:[{bad:'Missing break in colon form',why:'Falls into next case!',fix:'Add break; or use -> form.'},{bad:'switch (score > 90)',why:'Switch needs a value, not boolean range.',fix:'Use if-else for ranges.'},{bad:'No default',why:'Silent nothing for unknown.',fix:'Always add default.'}],practices:[{title:'Menu switch',task:'choice 1→“Idli”, 2→“Dosa”, else “Pick 1-2”. Use switch.',hint:'Arrow cases + default.',sol:'switch(choice){case 1->...; case 2->...; default->...;}'},{title:'Spot fall-through',task:'case 1: a(); case 2: b(); — if day=1, what runs?',hint:'No break!',sol:'Both a() and b() — fix with break.'}],quiz:[{id:'q1',prompt:'Missing break causes…',options:[{t:'Fall-through to next case',ok:true},{t:'Error always'},{t:'Nothing'},{t:'Loop'}],explain:'Colon form continues.'},{id:'q2',prompt:'Arrow form needs break?',options:[{t:'No',ok:true},{t:'Yes always'},{t:'Two breaks'},{t:'Only Fridays'}],explain:'-> is single-shot.'},{id:'q3',prompt:'Best switch use?',options:[{t:'Fixed choices (days, menu)',ok:true},{t:'Ranges like > 90'},{t:'True/false only'},{t:'Nothing'}],explain:'Labels, not ranges.'}],takeaways:['One value, many labels.','Arrow form avoids fall-through.','Always add default.'],recall:'When switch vs if-else?',todo:'Write a 3-item food menu with switch.',anim:{title:'Sorter',steps:[{caption:'Letter: day = 3.',html:'<div class="viz"><div class="varbox"><div class="nm">day</div><div class="vl">3</div></div></div>'},{caption:'Slides into slot 3.',html:'<div class="pipe"><div class="box">1</div><div class="box">2</div><div class="box"><b>3 ✓</b></div></div>'},{caption:'Outputs Wednesday.',html:'<div class="pipe"><div class="box"><b>Wednesday</b></div></div>'}]}},
'for-loops':{intro:'for repeats with a counter: start, keep-going check, step. Perfect when you know how many times.',question:'How would you instruct “clap 5 times” without writing “clap” 5 times?',analogy:'Washing machine: set 5 cycles (init i=0), check “done?” (i<5), run + tick (i++). Same three parts every load.',analogyFail:'Where it breaks: machines stop alone. Code with i-- instead of i++ may never stop — always verify the check moves toward false.',explain:['<b>for (int i = 0; i < 5; i++)</b>: init once, check each round, update after.','Index starts 0; <b>i < n</b> runs n times (0..n-1). <b><=</b> runs n+1 — classic off-by-one.','Body in braces; use i inside: print(i).'],code:`for (int i = 1; i <= 3; i++) {\n  System.out.println("Cycle " + i);\n}\nSystem.out.println("Done");`,codeNotes:['i=1, check ≤3, run, i++.','Runs for 1,2,3 then stops.','Done prints once after.'],output:'Cycle 1\nCycle 2\nCycle 3\nDone',why:'Three passes, then i=4 fails check, exit to Done.',sim:{kind:'loop',label:'Set cycles; watch iterations.',fields:[{v:'3'}]},mistakes:[{bad:'for (i = 0; i <= 5; i++) expecting 5 runs',why:'Runs 6 (0..5).',fix:'Use i < 5 for 5 runs.'},{bad:'Forgetting i++',why:'Check never changes → infinite.',fix:'Always update toward exit.'},{bad:'Using i after loop declared inside',why:'Scope ends at }.',fix:'Declare before if needed outside.'}],practices:[{title:'Count it',task:'How many prints? for (i=0;i<4;i++) print.',hint:'0,1,2,3.',sol:'4 prints.'},{title:'Sum 1..10',task:'Sum with a for loop.',hint:'total += i.',sol:'int t=0; for(i=1;i<=10;i++) t+=i; // 55'}],quiz:[{id:'q1',prompt:'for(i=0;i<5;i++) runs…',options:[{t:'5 times (0-4)',ok:true},{t:'6 times'},{t:'4 times'},{t:'Forever'}],explain:'< n gives n runs.'},{id:'q2',prompt:'Where does update happen?',options:[{t:'After each body run',ok:true},{t:'Before first check only'},{t:'Never'},{t:'At compile'}],explain:'Body → update → check.'},{id:'q3',prompt:'i <= n from 0 runs?',options:[{t:'n+1 times',ok:true},{t:'n times'},{t:'Once'},{t:'Zero'}],explain:'Inclusive adds one.'}],takeaways:['for = init; check; update.','i < n runs n times.','Update must approach exit.'],recall:'What are the three for-parts?',todo:'Print your name 5 times with a for.',anim:{title:'Washing cycles',steps:[{caption:'Init: i = 1.',html:'<div class="viz"><div class="varbox"><div class="nm">i</div><div class="vl">1</div></div></div>'},{caption:'Check 1≤3 ✓ → wash, i=2.',html:'<div class="viz"><div class="varbox"><div class="nm">i</div><div class="vl">2</div></div></div>'},{caption:'3 runs, then 4≤3 ❌ → Done.',html:'<div class="pipe"><div class="box">Cycle 1,2,3</div><span class="arr">→</span><div class="box">Done</div></div>'}]}},
'while-loops':{intro:'while repeats while a condition holds — ideal when you do not know how many rounds (password tries, reading input).',question:'When do you stop stirring soup?',analogy:'Taste-and-stir: while too salty, stir + taste again. do-while tastes first (always stirs once) — like “try the dish before judging”.',analogyFail:'Where it breaks: soup eventually balances. Code may never balance — always change something the condition watches.',explain:['<b>while (cond) { }</b> checks first (0+ runs). <b>do { } while (cond);</b> runs once, then checks.','Update inside! Forgot counter → infinite loop. Ctrl+C / stop button escapes.','Pick for when count known; while/do-while when rounds unknown.'],code:`int attempt = 0;\nint code = 0;\nwhile (code != 1234) {\n  attempt++;\n  code = 1234; // pretend user typed it\n}\nSystem.out.println("Unlocked in " + attempt);`,codeNotes:['Check before each round.','Body changes code toward exit.','attempt counts rounds.'],output:'Unlocked in 1',why:'First check 0≠1234 true → body sets 1234 → next check false → exit.',sim:{kind:'loop',label:'Rounds unknown: set max tries.',fields:[{v:'4'}]},mistakes:[{bad:'while (true) with no break',why:'Never exits.',fix:'Change condition inside or break.'},{bad:'do-while expecting 0 runs',why:'Always runs once.',fix:'Use while for maybe-zero.'},{bad:'Forgetting attempt++',why:'Same state forever.',fix:'Update the watched variable.'}],practices:[{title:'while or do?',task:'“Ask password until correct, at least once.” Which loop?',hint:'At least once = do-while.',sol:'do { ask } while (!correct);'},{title:'Countdown',task:'Print 3,2,1,Liftoff with while.',hint:'n=3; while(n>0).',sol:'while (n > 0) { print(n); n--; } print Liftoff.'}],quiz:[{id:'q1',prompt:'while checks…',options:[{t:'Before each run (maybe zero)',ok:true},{t:'After only'},{t:'Never'},{t:'At compile'}],explain:'Pre-check loop.'},{id:'q2',prompt:'do-while runs…',options:[{t:'At least once',ok:true},{t:'Maybe zero'},{t:'Exactly twice'},{t:'Never'}],explain:'Post-check.'},{id:'q3',prompt:'Infinite loop fix?',options:[{t:'Change condition variable inside',ok:true},{t:'Add comments'},{t:'Rename i'},{t:'Delete braces'}],explain:'Move toward false.'}],takeaways:['while = unknown rounds, pre-check.','do-while always runs once.','Always progress toward exit.'],recall:'When while vs for vs do-while?',todo:'Countdown with while; then with do-while.',anim:{title:'Taste loop',steps:[{caption:'Check: salty? yes → stir.',html:'<div class="pipe"><div class="box">salty? ✓</div><span class="arr">→</span><div class="box">stir</div></div>'},{caption:'Taste again: balanced? no → stir.',html:'<div class="pipe"><div class="box">balanced? ❌</div><span class="arr">→</span><div class="box">stir</div></div>'},{caption:'Balanced → serve, exit.',html:'<div class="pipe"><div class="box">balanced ✓</div><span class="arr">→</span><div class="box">serve 🍲</div></div>'}]}},
'break-continue':{intro:'break = emergency exit. continue = skip this dance move but stay at the party. Both reshape loops without nesting.',question:'In a bus queue, what is the difference between leaving and letting one person pass?',analogy:'Hopscotch: continue = skip square 4, keep hopping. break = stop game, go home. Skipping ≠ quitting.',analogyFail:'Where it breaks: skipping every square finishes nothing. Overused continue/break hides logic — prefer clear conditions.',explain:['<b>continue</b>: jump to next iteration (update still runs in for). <b>break</b>: exit loop now.','Use continue to skip bad data; break on “found it!” to stop searching.','Both pair with if; avoid break soup — one exit is clearest.'],code:`for (int i = 1; i <= 5; i++) {\n  if (i == 3) continue; // skip 3\n  if (i == 5) break;    // stop before 5\n  System.out.print(i + " ");\n}\n// prints: 1 2 4`,codeNotes:['i=3 skipped, loop continues.','i=5 exits immediately.','Output 1 2 4.'],output:'1 2 4',why:'Continue jumps over print for 3; break abandons loop at 5.',sim:{kind:'loop',label:'Skip vs stop: set rounds.',fields:[{v:'5'}]},mistakes:[{bad:'break expecting skip',why:'Break quits everything.',fix:'Use continue to skip one.'},{bad:'continue in while without update',why:'Skips the update → infinite!',fix:'Update before continue, or use for.'},{bad:'Many breaks everywhere',why:'Maze logic.',fix:'One break on found; else restructure.'}],practices:[{title:'Skip evens?',task:'Print odds 1..9 using continue.',hint:'if even → continue.',sol:'if (i % 2 == 0) continue; print(i);'},{title:'Find and stop',task:'Stop at first 7 in 1..10 with break.',hint:'if == 7 break.',sol:'Loop; if (i==7){found; break;}' }],quiz:[{id:'q1',prompt:'continue does…',options:[{t:'Skip rest of this round, next round',ok:true},{t:'Exit loop'},{t:'Restart program'},{t:'Skip all future'}],explain:'One skip.'},{id:'q2',prompt:'break does…',options:[{t:'Exit the loop now',ok:true},{t:'Skip one'},{t:'Pause'},{t:'Nothing'}],explain:'Emergency exit.'},{id:'q3',prompt:'Output of code above?',options:[{t:'1 2 4',ok:true},{t:'1 2 3 4 5'},{t:'1 2 4 5'},{t:'3 5'}],explain:'Skip 3, stop at 5.'}],takeaways:['continue skips one round.','break exits the loop.','In while, update before continue.'],recall:'Give one good use for each.',todo:'Print 1..10 skipping multiples of 3.',anim:{title:'Hopscotch',steps:[{caption:'Hop 1, 2 normally.',html:'<div class="pipe"><div class="box">1 ✓</div><div class="box">2 ✓</div></div>'},{caption:'3: continue — skip, keep going.',html:'<div class="pipe"><div class="box">3 ⏭️ skip</div><span class="arr">→</span><div class="box">4 ✓</div></div>'},{caption:'5: break — game over.',html:'<div class="pipe"><div class="box">5 🛑 stop</div></div>'}]}},
'nested-loops':{intro:'A loop inside a loop draws tables, grids, and patterns. Outer = rows, inner = seats per row.',question:'How does a cinema fill 5 rows × 8 seats without naming each seat?',analogy:'Cinema usher: outer walks rows 1-5; for each row, inner counts seats 1-8. Total visits = rows × seats. Clocks do this too (hours × minutes).',analogyFail:'Where it breaks: ushers get tired quadratically. 100×100 = 10,000 visits — nested loops can get slow fast.',explain:['<b>Outer</b> picks row; <b>inner</b> runs fully per row. Use different counters (r, c).','Total = rows × cols. Trace small (2×3) before big.','Print grids: inner print(), outer println() for new row.'],code:`for (int r = 1; r <= 2; r++) {\n  for (int c = 1; c <= 3; c++) {\n    System.out.print(r + "x" + c + " ");\n  }\n  System.out.println();\n}`,codeNotes:['Row 1: 1x1 1x2 1x3.','Row 2: 2x1 2x2 2x3.','println breaks the row.'],output:'1x1 1x2 1x3 \n2x1 2x2 2x3',why:'Inner completes 3 per outer; 2×3 = 6 prints over 2 lines.',sim:{kind:'loop',label:'Rows × seats: set rows.',fields:[{v:'2'}]},mistakes:[{bad:'Reusing i in both loops',why:'Inner corrupts outer counter.',fix:'Use r and c.'},{bad:'println inside inner',why:'One per cell, not per row.',fix:'print in inner, println in outer.'},{bad:'Huge nesting (1000×1000)',why:'Million visits — slow.',fix:'Rethink or break early.'}],practices:[{title:'Count visits',task:'3 rows × 4 seats = ?',hint:'Multiply.',sol:'12 inner runs.'},{title:'Star triangle',task:'Print *, **, *** with nested loops.',hint:'Row r prints r stars.',sol:'Outer r=1..3, inner c=1..r print *.'}],quiz:[{id:'q1',prompt:'2 rows × 3 cols = inner runs?',options:[{t:'6',ok:true},{t:'5'},{t:'4'},{t:'9'}],explain:'Multiply.'},{id:'q2',prompt:'Use different counters because…',options:[{t:'Sharing corrupts the outer count',ok:true},{t:'Java requires a-z'},{t:'Speed'},{t:'Style only'}],explain:'Inner would overwrite.'},{id:'q3',prompt:'New row via…',options:[{t:'println in outer after inner',ok:true},{t:'print in inner only'},{t:'break always'},{t:'No newline'}],explain:'Row break after seats.'}],takeaways:['Outer rows, inner seats.','Total = rows × cols.','Different counters; println per row.'],recall:'How many runs for 4×5?',todo:'Print a 4×4 multiplication corner.',anim:{title:'Cinema fill',steps:[{caption:'Row 1: seats 1-3.',html:'<div class="pipe"><div class="box">Row1: 1x1 1x2 1x3</div></div>'},{caption:'Row 2: seats 1-3.',html:'<div class="pipe"><div class="box">Row2: 2x1 2x2 2x3</div></div>'},{caption:'Total 6 = 2 × 3.',html:'<div class="viz"><div class="varbox"><div class="nm">total</div><div class="vl">6</div></div></div>'}]}},
'methods':{intro:'A method is a reusable recipe card: name it once, cook it anywhere. No more copy-paste cooking.',question:'Why do restaurants print menus instead of explaining each dish table by table?',analogy:'Vending machine: press B3 (call), machine runs hidden steps, drops snack (maybe returns change). You reuse without knowing insides.',analogyFail:'Where it breaks: machines jam on bad coins. Methods jam on bad inputs — validate or document.',explain:['<b>Define</b>: static void greet() { ... }. <b>Call</b>: greet(); runs it.','Calls jump in, run, jump back. Same card reused 100×.','<b>void</b> = no takeaway; value methods return something (next lesson).'],code:`public class Chef {\n  static void greet() {\n    System.out.println("Welcome!");\n  }\n  public static void main(String[] args) {\n    greet();\n    greet();\n  }\n}`,codeNotes:['greet defined once.','Called twice — runs twice.','Change card once, both improve.'],output:'Welcome!\nWelcome!',why:'Each call executes the body, returns, continues after the call.',sim:{kind:'concat',label:'Call twice, serve twice.',fields:[{v:'Welcome'},{v:'!'}]},mistakes:[{bad:'Defining but never calling',why:'Card stays in drawer.',fix:'Call it from main.'},{bad:'Calling before defined? (fine!)',why:'Order flexible within class.',fix:'Relax — define anywhere in class.'},{bad:'Huge main with repeats',why:'Copy-paste rot.',fix:'Extract a method.'}],practices:[{title:'Extract it',task:'Two identical print blocks → one method.',hint:'Name it printBill().',sol:'static void printBill(){...} call twice.'},{title:'Call count',task:'greet() 3 times → how many lines?',hint:'Each call prints once.',sol:'3 lines.'}],quiz:[{id:'q1',prompt:'Method benefit?',options:[{t:'Write once, reuse many times',ok:true},{t:'Runs faster magically'},{t:'Deletes code'},{t:'Avoids names'}],explain:'Reuse + single fix point.'},{id:'q2',prompt:'greet() with no call…',options:[{t:'Never runs',ok:true},{t:'Runs once'},{t:'Runs always'},{t:'Errors'}],explain:'Definition ≠ execution.'},{id:'q3',prompt:'void means…',options:[{t:'Returns nothing',ok:true},{t:'Empty file'},{t:'No parameters'},{t:'Secret'}],explain:'No takeaway value.'}],takeaways:['Define once, call often.','Calls jump in and back.','void = no return value.'],recall:'What happens at a method call, step by step?',todo:'Extract one repeated block into a method.',anim:{title:'Vending calls',steps:[{caption:'Press B3: call greet().',html:'<div class="pipe"><div class="box">main</div><span class="arr">→</span><div class="box">greet()</div></div>'},{caption:'Machine runs hidden steps.',html:'<div class="pipe"><div class="box">println Welcome!</div></div>'},{caption:'Snack drops, back to main.',html:'<div class="pipe"><div class="box">greet done</div><span class="arr">→</span><div class="box">main resumes</div></div>'}]}},
'params-return':{intro:'Parameters are order slips (inputs); return is the served plate (output). void serves nothing back.',question:'How does one kitchen make “less spicy, extra rice” for each table differently?',analogy:'Service counter: slip says paneer, spice 2 (parameters). Kitchen returns a plate (return value) or just shouts “done!” (void). Different slips, same kitchen.',analogyFail:'Where it breaks: kitchens guess missing slips. Java refuses — wrong count/type of arguments is a compile error.',explain:['<b>Parameter</b> = slot in definition. <b>Argument</b> = value at call. Types must match.','<b>return value;</b> sends back one value and exits. Caller stores/prints it.','<b>void</b> returns nothing. Max one return value — pack more in arrays/objects later.'],code:`static int add(int a, int b) {\n  return a + b;\n}\n// call:\nint s = add(4, 5);\nSystem.out.println(s); // 9`,codeNotes:['a,b are slots; 4,5 are values.','return sends 9 back.','s catches the plate.'],output:'9',why:'add computes 4+5, returns 9, println shows it.',sim:{kind:'arith',label:'Order slip: pick a, b.',fields:[{v:'4'},{o:['+']},{v:'5'}]},mistakes:[{bad:'add(4) missing arg',why:'Slot unfilled.',fix:'add(4, 5).'},{bad:'Forgetting to use return value',why:'Plate gets cold (ignored).',fix:'int s = add(4,5);'},{bad:'return; in int method',why:'Must serve the declared type.',fix:'return a + b;'}],practices:[{title:'Write square',task:'int square(int n) returning n*n.',hint:'return n * n;',sol:'static int square(int n){ return n*n; }'},{title:'void or value?',task:'printBill vs getTotal: which returns?',hint:'Print = void; compute = value.',sol:'printBill void; getTotal returns double.'}],quiz:[{id:'q1',prompt:'Parameter vs argument?',options:[{t:'Slot in definition vs value at call',ok:true},{t:'Same thing'},{t:'Return vs void'},{t:'Loop vs if'}],explain:'Slip design vs filled slip.'},{id:'q2',prompt:'add(4,5) with (4) missing…',options:[{t:'Compile error',ok:true},{t:'Runs as 9'},{t:'Uses 0'},{t:'Asks user'}],explain:'Count/type must match.'},{id:'q3',prompt:'return does…',options:[{t:'Send value back + exit method',ok:true},{t:'Print always'},{t:'Loop again'},{t:'Delete method'}],explain:'One plate, then back.'}],takeaways:['Parameters in, return out.','Types/counts must match.','Catch the return value.'],recall:'Can a method return two values directly?',todo:'Write double/total method for a bill.',anim:{title:'Order slip',steps:[{caption:'Slip: add(4, 5).',html:'<div class="pipe"><div class="box">a=4, b=5</div></div>'},{caption:'Kitchen: 4+5.',html:'<div class="pipe"><div class="box">compute 9</div></div>'},{caption:'Serve plate 9 back.',html:'<div class="pipe"><div class="box"><b>return 9</b></div><span class="arr">→</span><div class="box">s = 9</div></div>'}]}},
'scope':{intro:'Scope = where a variable is visible and alive. Braces are hotel rooms — what happens inside usually stays inside.',question:'Why can’t the lobby hear your shower singing?',analogy:'Hotel rooms: lobby variable visible everywhere on floor; room variable dies at checkout (}). Inner rooms see outer; outer cannot see inner.',analogyFail:'Where it breaks: hotels share Wi-Fi. Code rooms share nothing unless passed as parameters — no snooping.',explain:['<b>Block scope</b>: declared in { } lives there only. Loop counter dies after loop.','<b>Shadowing</b>: inner same-name hides outer — confusing, avoid.','<b>Lifetime</b>: created at declaration, destroyed at }. Use smallest scope.'],code:`int hall = 1;\nif (true) {\n  int room = 2;\n  System.out.println(hall + room); // 3\n}\nSystem.out.println(hall); // 1\n// System.out.println(room); // ERROR: gone`,codeNotes:['hall visible inside.','room dies at }.','Uncommented line fails.'],output:'3\n1',why:'Inner sees outer; outer cannot see inner after checkout.',sim:{kind:'arith',label:'Rooms: combine hall + room.',fields:[{v:'1'},{o:['+']},{v:'2'}]},mistakes:[{bad:'Using loop i after loop',why:'Checked out.',fix:'Declare before loop if needed.'},{bad:'Shadowing: two ages',why:'Which age?!',fix:'Rename inner.'},{bad:'Giant method-wide vars',why:'Everything sees, bugs hide.',fix:'Declare close to use.'}],practices:[{title:'Alive?',task:'{ int q=5; } print(q) — works?',hint:'Checked out.',sol:'No — out of scope.'},{title:'Fix shadow',task:'Fix: int x=1; { int x=2; }',hint:'Rename.',sol:'int y = 2; inside.'}],quiz:[{id:'q1',prompt:'Room variable after } …',options:[{t:'Gone (out of scope)',ok:true},{t:'Still usable'},{t:'Moves to lobby'},{t:'Doubles'}],explain:'Lifetime ends.'},{id:'q2',prompt:'Inner block sees…',options:[{t:'Outer variables',ok:true},{t:'Nothing'},{t:'Future code'},{t:'Other files'}],explain:'Inner sees outer.'},{id:'q3',prompt:'Shadowing is…',options:[{t:'Same name hiding outer — avoid',ok:true},{t:'Required'},{t:'A loop'},{t:'A type'}],explain:'Confusing; rename.'}],takeaways:['Braces bound life.','Inner sees outer, not reverse.','Smallest scope wins.'],recall:'Where should you declare a loop-only variable?',todo:'Shrink one wide variable’s scope.',anim:{title:'Hotel rooms',steps:[{caption:'Lobby hall = 1 (floor sees).',html:'<div class="viz"><div class="varbox"><div class="nm">hall</div><div class="vl">1</div></div></div>'},{caption:'Room 2 opens: sees hall + room.',html:'<div class="viz"><div class="varbox"><div class="nm">room</div><div class="vl">2</div></div></div>'},{caption:'Checkout: room gone.',html:'<div class="pipe"><div class="box">room ❌ gone</div><div class="box">hall ✓ stays</div></div>'}]}},
'debugging':{intro:'Bugs are normal. Pros just find them faster: read the error, reproduce, narrow, fix one thing, re-test.',question:'If toast burns, do you rebuild the kitchen?',analogy:'Detective kit: victim (error line), witnesses (prints), alibis (inputs). Check the first error — later ones are often gossip.',analogyFail:'Where it breaks: detectives guess motives. Debuggers verify — change one thing, re-run, observe. No horoscope fixes.',explain:['4 kinds: <b>syntax</b> (red, no build), <b>compile-type</b> (wrong types), <b>runtime exception</b> (crash mid-run), <b>logic</b> (runs, wrong answer).','Read <b>stack trace</b> top→file:line. “NullPointerException at Bill.java:12” = visit line 12.','Strategy: reproduce → print suspects → binary-search (disable half) → fix first cause.'],code:`int[] m = {80, 90};\nSystem.out.println(m[0]); // 80 ok\n// System.out.println(m[5]); // crash!\nint total = m[0] + m[1];\nSystem.out.println(total); // 170`,codeNotes:['Valid index prints.','Bad index would crash — commented safe.','Logic check: sum correct?'],output:'80\n170',why:'In-bounds works. Out-of-bounds would throw ArrayIndexOutOfBoundsException at that line.',sim:{kind:'array',label:'Try indexes 0-1 vs 5.',fields:[{v:'1'}]},mistakes:[{bad:'Fixing the last of 20 errors first',why:'Cascade from first.',fix:'Fix #1, rebuild.'},{bad:'Random changes everywhere',why:'Masks the cause.',fix:'One change, re-run.'},{bad:'Ignoring logic bugs (wrong total)',why:'No red != correct.',fix:'Test with known answers.'}],practices:[{title:'Read it',task:'“NullPointerException at Ask.java:9” — where?',hint:'File:line.',sol:'Ask.java line 9, something null there.'},{title:'Bisect',task:'100-line wrong output. First move?',hint:'Disable half.',sol:'Comment half, see if bug stays — narrow.'}],quiz:[{id:'q1',prompt:'Which runs but gives wrong answer?',options:[{t:'Logic error',ok:true},{t:'Syntax error'},{t:'Missing file'},{t:'No error kind'}],explain:'Silent wrongness.'},{id:'q2',prompt:'Fix many errors: start where?',options:[{t:'First error',ok:true},{t:'Last error'},{t:'Random'},{t:'Delete all'}],explain:'First causes cascade.'},{id:'q3',prompt:'m[5] on length-2 gives…',options:[{t:'ArrayIndexOutOfBoundsException',ok:true},{t:'0 quietly'},{t:'5'},{t:'Compiles away'}],explain:'Bounds enforced at runtime.'}],takeaways:['4 error kinds; read file:line.','First error first; one fix at a time.','Test known answers for logic.'],recall:'Name the 4 bug kinds with an example each.',todo:'Keep a bug diary: error, cause, fix.',anim:{title:'Detective',steps:[{caption:'Victim: error at line 12.',html:'<div class="pipe"><div class="box"><b>Bill.java:12</b><br>NullPointer!</div></div>'},{caption:'Witnesses: prints reveal null.',html:'<div class="pipe"><div class="box">print s → null ⚠️</div></div>'},{caption:'Fix once, re-run, closed ✓.',html:'<div class="pipe"><div class="box">guard null → pass ✓</div></div>'}]}},
'arrays':{intro:'An egg tray holds exactly 12 eggs — same size, numbered slots. Arrays hold many values of one type in numbered boxes.',question:'Why not carry 30 eggs in your hands?',analogy:'Egg tray: fixed 12 slots, slot 0 first. Tray cannot grow — need more? Buy a bigger tray (new array) or switch to a expandable basket (ArrayList later).',analogyFail:'Where it breaks: eggs differ. Array slots share one type — no mixing ints and strings.',explain:['<b>int[] a = new int[3];</b> or <b>int[] a = {10, 20, 30};</b> Length fixed: <b>a.length</b>.','Slots numbered <b>0..length-1</b>. Default fills 0 / false / null.','Arrays are objects — reference points to the tray.'],code:`int[] eggs = {10, 20, 30};\nSystem.out.println(eggs.length); // 3\nSystem.out.println(eggs[0]);     // 10\neggs[1] = 99;\nSystem.out.println(eggs[1]);     // 99`,codeNotes:['Length 3, fixed.','Read slot 0.','Overwrite slot 1.'],output:'3\n10\n99',why:'Tray of 3; slots read/written by number; length never changes.',sim:{kind:'array',label:'Open slots 0-2; try 5.',fields:[{v:'0'}]},mistakes:[{bad:'int[] a = new int[-2];',why:'Negative tray impossible.',fix:'Positive size.'},{bad:'Expecting growth with a[3] = x',why:'Fixed! Slot 3 missing on length-3.',fix:'New bigger array or ArrayList.'},{bad:'int[] a; print(a[0])',why:'No tray built (null).',fix:'a = new int[3]; first.'}],practices:[{title:'Last slot',task:'Length 5: index of last?',hint:'length-1.',sol:'4.'},{title:'Defaults',task:'new int[3] holds?',hint:'Zeros.',sol:'[0, 0, 0].'}],quiz:[{id:'q1',prompt:'int[3] valid indexes?',options:[{t:'0,1,2',ok:true},{t:'1,2,3'},{t:'0-3'},{t:'Any'}],explain:'0-based to length-1.'},{id:'q2',prompt:'Arrays can…',options:[{t:'Hold one type, fixed length',ok:true},{t:'Mix types, grow freely'},{t:'Hold nothing'},{t:'Change type'}],explain:'One type, fixed slots.'},{id:'q3',prompt:'eggs.length gives?',options:[{t:'3',ok:true},{t:'2'},{t:'30'},{t:'Index'}],explain:'Slot count.'}],takeaways:['One type, numbered from 0.','Length fixed at birth.','length counts slots.'],recall:'How do you get the last index?',todo:'Store 5 friend ages; print first and last.',anim:{title:'Egg tray',steps:[{caption:'New tray of 3: [?, ?, ?].',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">?</div></div><div class="memcell"><div class="idx">1</div><div class="val">?</div></div><div class="memcell"><div class="idx">2</div><div class="val">?</div></div></div>'},{caption:'Fill: 10, 20, 30.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">10</div></div><div class="memcell"><div class="idx">1</div><div class="val">20</div></div><div class="memcell"><div class="idx">2</div><div class="val">30</div></div></div>'},{caption:'eggs[1] = 99 swaps slot 1.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">10</div></div><div class="memcell"><div class="idx">1</div><div class="val">99 ✨</div></div><div class="memcell"><div class="idx">2</div><div class="val">30</div></div></div>'}]}},
'indexing-bounds':{intro:'Index 0 is first, length-1 is last. Touching outside is like knocking on a door that does not exist — Java stops you loudly.',question:'Why do buildings skip “floor 0” in some countries but programmers love it?',analogy:'Hotel floors 0-4 (5 floors). Last = floors-1 = 4. Knocking on floor 9 → security (exception) escorts you out.',analogyFail:'Where it breaks: hotels may forgive. Java never forgives out-of-bounds — instant ArrayIndexOutOfBoundsException.',explain:['<b>First = 0, last = length-1</b>. Loop: <b>i < a.length</b>, never <=.','<b>a[a.length]</b> always crashes. Check bounds before wild indexes.','Use <b>length</b> (arrays) vs <b>length()</b> (strings) — no brackets for arrays!'],code:`int[] a = {5, 6, 7};\nSystem.out.println(a[0]);          // 5\nSystem.out.println(a[a.length-1]); // 7\n// System.out.println(a[3]); // crash: 0..2 only`,codeNotes:['First slot 0.','Last = length-1.','Index 3 missing → crash.'],output:'5\n7',why:'Length 3 → doors 0,1,2. Door 3 does not exist.',sim:{kind:'array',label:'Knock on doors 0-5.',fields:[{v:'3'}]},mistakes:[{bad:'for (i = 0; i <= a.length; i++)',why:'Visits one ghost door.',fix:'i < a.length.'},{bad:'a.length() with brackets',why:'Arrays use length (field-like).',fix:'a.length — strings use length().'},{bad:'Guessing “last = length”',why:'Off by one.',fix:'Last = length - 1.'}],practices:[{title:'Last of 7',task:'Length-7 array: last index?',hint:'-1.',sol:'6.'},{title:'Fix loop',task:'Fix <= to visit exactly length.',hint:'< length.',sol:'for (i=0;i<a.length;i++)'}],quiz:[{id:'q1',prompt:'Length-4 last index?',options:[{t:'3',ok:true},{t:'4'},{t:'0'},{t:'-1'}],explain:'length-1.'},{id:'q2',prompt:'a[4] on length-4?',options:[{t:'ArrayIndexOutOfBoundsException',ok:true},{t:'0'},{t:'null'},{t:'4'}],explain:'Doors 0-3 only.'},{id:'q3',prompt:'Arrays use…',options:[{t:'a.length (no brackets)',ok:true},{t:'a.length()'},{t:'a.size()'},{t:'len(a)'}],explain:'Field-like; strings differ.'}],takeaways:['0 first, length-1 last.','Loop with < length.','Outside → loud exception.'],recall:'Doors 0..n-1: how many doors for length n?',todo:'Print first, middle, last of an array safely.',anim:{title:'Hotel doors',steps:[{caption:'5 floors: doors 0-4.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">5</div></div><div class="memcell"><div class="idx">1</div><div class="val">6</div></div><div class="memcell"><div class="idx">2</div><div class="val">7</div></div></div>'},{caption:'Knock 2 → opens (7).',html:'<div class="pipe"><div class="box">a[2] → 7 ✓</div></div>'},{caption:'Knock 3 → security! 🚨',html:'<div class="pipe"><div class="box">a[3] → 💥 out of bounds</div></div>'}]}},
'traverse-arrays':{intro:'Visiting every slot in order — to print, sum, or upgrade — is traversing. Loops are the tour bus.',question:'How do you water 20 plants without missing one?',analogy:'Tour bus with numbered seats: classic for counts the seats (needs index), for-each just greets each passenger (no index). To change seats, need the classic bus.',analogyFail:'Where it breaks: for-each gives a photo copy of primitives — editing the copy does not change the tray.',explain:['<b>for (i...)</b> when you need index or must write: a[i] = ....','<b>for (int v : a)</b> to read simply. <b>v</b> is a copy for primitives.','Accumulate: sum, count, transform with the right bus.'],code:`int[] m = {80, 90, 70};\nint sum = 0;\nfor (int v : m) sum += v;\nSystem.out.println(sum); // 240\nfor (int i = 0; i < m.length; i++) m[i] += 5;\nSystem.out.println(m[0]); // 85`,codeNotes:['for-each reads all.','Classic loop writes all (+5).','Sum 240, first now 85.'],output:'240\n85',why:'Read tour sums; write tour upgrades each slot.',sim:{kind:'loop',label:'Tour 3 seats.',fields:[{v:'3'}]},mistakes:[{bad:'for (v : m) v += 5; (int[])',why:'Edits the copy!',fix:'Use index loop to write.'},{bad:'<= length in tour',why:'Ghost seat crash.',fix:'< length.'},{bad:'Forgetting sum = 0 init',why:'Garbage start.',fix:'Initialize accumulators.'}],practices:[{title:'Average',task:'Average of {80,90,70}.',hint:'sum / length as double.',sol:'240 / 3.0 = 80.0'} ,{title:'Double it',task:'Double each slot with index loop.',hint:'a[i] *= 2.',sol:'for(i...) a[i] *= 2;'}],quiz:[{id:'q1',prompt:'Need to WRITE slots: use…',options:[{t:'Classic index loop',ok:true},{t:'for-each on primitives'},{t:'No loop'},{t:'switch'}],explain:'Need the address.'},{id:'q2',prompt:'for-each v on int[] is…',options:[{t:'A copy (edits lost)',ok:true},{t:'The real slot'},{t:'The index'},{t:'Length'}],explain:'Copy semantics.'},{id:'q3',prompt:'Sum above?',options:[{t:'240',ok:true},{t:'170'},{t:'245'},{t:'0'}],explain:'80+90+70.'}],takeaways:['Read: for-each. Write: index loop.','Init accumulators.','< length always.'],recall:'When must you use the index loop?',todo:'Sum and average your 5 ages array.',anim:{title:'Tour bus',steps:[{caption:'Stop 0: greet 80.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">80 ✓</div></div><div class="memcell"><div class="idx">1</div><div class="val">90</div></div><div class="memcell"><div class="idx">2</div><div class="val">70</div></div></div>'},{caption:'Stop 1: greet 90, sum 170.',html:'<div class="viz"><div class="memcell"><div class="idx">1</div><div class="val">90 ✓</div></div></div>'},{caption:'Stop 2: greet 70, sum 240.',html:'<div class="viz"><div class="varbox"><div class="nm">sum</div><div class="vl">240</div></div></div>'}]}},
'arrays-2d':{intro:'A 2D array is a grid: rows of rows. Cinema seats, chessboards, marks tables — [row][seat].',question:'How do you find seat “row C, seat 4” without checking every chair?',analogy:'Cinema: block C, chair 4 → grid[2][3] (0-based). Jagged rows exist (balcony shorter) — each row is its own array.',analogyFail:'Where it breaks: cinemas label from 1. Code labels from 0 — grid[0][0] is the true first seat.',explain:['<b>int[][] g = new int[2][3];</b> 2 rows × 3 cols. <b>g[r][c]</b> one seat.','<b>g.length</b> rows; <b>g[r].length</b> cols in row r (may vary).','Nested loops: outer rows, inner cols.'],code:`int[][] seats = {{1, 0, 1}, {0, 1, 1}};\nSystem.out.println(seats[0][1]); // 0 (taken?)\nSystem.out.println(seats.length + "x" + seats[0].length);`,codeNotes:['2 rows, 3 cols.','Row 0 seat 1 = 0.','Size 2x3.'],output:'0\n2x3',why:'Grid read by two numbers; lengths per dimension.',sim:{kind:'array',label:'Pick a seat index.',fields:[{v:'1'}]},mistakes:[{bad:'seats[3][0] on 2 rows',why:'Row 3 missing.',fix:'Rows 0..1 only.'},{bad:'Assuming all rows equal',why:'Jagged possible.',fix:'Use g[r].length per row.'},{bad:'Single loop for grid',why:'Visits rows, not seats.',fix:'Nest two loops.'}],practices:[{title:'First seat',task:'Value at seats[0][0]?',hint:'Row0 col0.',sol:'1.'},{title:'Count free',task:'Count 1s (free) with nested loops.',hint:'if == 1 count++.',sol:'4 free seats.'}],quiz:[{id:'q1',prompt:'seats[0][1] means…',options:[{t:'Row 0, col 1',ok:true},{t:'Row 1, col 0'},{t:'Seat 1 total'},{t:'Row 1 col 1'}],explain:'[row][col].'},{id:'q2',prompt:'Rows count via…',options:[{t:'g.length',ok:true},{t:'g[0].length only'},{t:'g.size'},{t:'len(g)'}],explain:'Outer length.'},{id:'q3',prompt:'Fill a grid: use…',options:[{t:'Nested loops',ok:true},{t:'One if'},{t:'switch'},{t:'No loops'}],explain:'Rows × cols.'}],takeaways:['Grid = array of arrays.','[row][col], both 0-based.','Rows: g.length; cols: g[r].length.'],recall:'How do you count all seats?',todo:'Model a 3×3 tic-tac-toe board.',anim:{title:'Cinema grid',steps:[{caption:'2 blocks × 3 chairs.',html:'<div class="viz"><div class="memcell"><div class="idx">0,0</div><div class="val">1</div></div><div class="memcell"><div class="idx">0,1</div><div class="val">0</div></div><div class="memcell"><div class="idx">0,2</div><div class="val">1</div></div></div>'},{caption:'Seat [0][1] = 0 (taken).',html:'<div class="pipe"><div class="box">row 0, seat 1 → 0</div></div>'},{caption:'Row 1 next: 0 1 1.',html:'<div class="viz"><div class="memcell"><div class="idx">1,0</div><div class="val">0</div></div><div class="memcell"><div class="idx">1,1</div><div class="val">1</div></div><div class="memcell"><div class="idx">1,2</div><div class="val">1</div></div></div>'}]}},
'string-methods':{intro:'Strings come with a toolkit: measure, peek, slice, compare, clean. Learn 7 and you handle 90% of text tasks.',question:'If books had instant tools — length, find word, tear chapter — which would you use daily?',analogy:'Swiss knife: length() ruler, charAt() tweezers, substring() scissors, equals() scale, toUpperCase() megaphone, trim() towel, split() cutter.',analogyFail:'Where it breaks: scissors on strings return new paper — originals never cut (immutability, next lesson).',explain:['<b>length()</b>, <b>charAt(i)</b>, <b>substring(a,b)</b> (b excluded!), <b>indexOf(x)</b> (-1 = missing).','<b>equals()</b> content; <b>equalsIgnoreCase()</b>; <b>toUpperCase/LowerCase()</b>; <b>trim()</b>; <b>split(",")</b>.','Indexes 0-based; charAt(length) crashes like arrays.'],code:`String s = "  Java Rocks  ";\nSystem.out.println(s.trim());\nSystem.out.println(s.trim().length());\nSystem.out.println("Java".equals("java"));\nSystem.out.println("Java".substring(0, 2));`,codeNotes:['trim removes edge spaces.','Length after trim = 10.','substring(0,2) = Ja.'],output:'Java Rocks\n10\nfalse\nJa',why:'Cleaned, measured, compared (case matters!), sliced.',sim:{kind:'concat',label:'Clean + slice text.',fields:[{v:'  Java '},{v:'Rocks'}]},mistakes:[{bad:'s == "Java"',why:'House compare.',fix:'s.equals("Java")'},{bad:'substring(0, 5) expecting 5 chars inclusive',why:'End excluded.',fix:'0..5 gives 0-4.'},{bad:'Forgetting trim result',why:'Returns new string!',fix:'s = s.trim();'}],practices:[{title:'First 3',task:'First 3 chars of name.',hint:'substring(0,3).',sol:'name.substring(0, 3);'},{title:'Find @',task:'Check email contains @.',hint:'indexOf != -1.',sol:'email.indexOf("@") != -1;'}],quiz:[{id:'q1',prompt:'"Java".substring(0,2)?',options:[{t:'Ja',ok:true},{t:'Jav'},{t:'av'},{t:'JaV'}],explain:'End excluded.'},{id:'q2',prompt:'indexOf missing gives?',options:[{t:'-1',ok:true},{t:'0'},{t:'null'},{t:'Error'}],explain:'-1 = absent.'},{id:'q3',prompt:'Compare text?',options:[{t:'equals()',ok:true},{t:'=='},{t:'='},{t:'!='}],explain:'Content check.'}],takeaways:['7 tools cover most text jobs.','End index excluded; -1 means missing.','Methods return new strings.'],recall:'Which method finds a word’s position?',todo:'Clean + slice your full name 3 ways.',anim:{title:'Swiss knife',steps:[{caption:'Ruler: length 10.',html:'<div class="pipe"><div class="box">"Java Rocks" → 10</div></div>'},{caption:'Tweezers: charAt(0) = J.',html:'<div class="pipe"><div class="box">pick slot 0 → J</div></div>'},{caption:'Scissors: substring(0,2) = Ja.',html:'<div class="pipe"><div class="box">cut 0..2 → Ja ✂️</div></div>'}]}},
'string-immut':{intro:'Strings cannot change after birth. Every “edit” secretly builds a new string — safe to share, but costly in loops.',question:'Why are printed books trustworthy but whiteboards not?',analogy:'Printed book vs whiteboard. s.toUpperCase() photocopies the book in caps; original book unchanged. Whiteboard (StringBuilder) edits in place.',analogyFail:'Where it breaks: photocopying 10,000 pages (loop +) wastes paper/time — use the whiteboard then.',explain:['<b>Immutable</b> = no in-place edits. s.toUpperCase() returns new; s same unless reassigned.','Why: safe sharing, thread-safe, string pool savings.','Loop building? Use <b>StringBuilder</b> (next). Reassign: s = s.trim();'],code:`String s = "java";\ns.toUpperCase();\nSystem.out.println(s); // still java!\ns = s.toUpperCase();\nSystem.out.println(s); // JAVA`,codeNotes:['Line 2 result ignored — lost!','Original untouched.','Reassign keeps the new one.'],output:'java\nJAVA',why:'No mutation; only reassignment changes what s points to.',sim:{kind:'concat',label:'Ignored result vs saved.',fields:[{v:'java'},{v:'!'}]},mistakes:[{bad:'s.toUpperCase(); expecting change',why:'Result discarded.',fix:'s = s.toUpperCase();'},{bad:'Loop s += piece 10k times',why:'10k photocopies — slow.',fix:'StringBuilder for loops.'},{bad:'== after toUpperCase',why:'New house anyway.',fix:'equals + reassign.'}],practices:[{title:'Fix it',task:'Fix: s.trim(); print(s) still spaced.',hint:'Reassign.',sol:'s = s.trim();'},{title:'Pool guess',task:'"a"+"b" in loop vs builder — which faster?',hint:'Builder.',sol:'StringBuilder; + copies each round.'}],quiz:[{id:'q1',prompt:'s.toUpperCase() without assign…',options:[{t:'Original unchanged',ok:true},{t:'s becomes upper'},{t:'Error'},{t:'Deletes s'}],explain:'New string discarded.'},{id:'q2',prompt:'Why immutable?',options:[{t:'Safe sharing + pooling',ok:true},{t:'To annoy'},{t:'Saves typing'},{t:'No reason'}],explain:'Share without fear.'},{id:'q3',prompt:'Loop-build 10k pieces: use…',options:[{t:'StringBuilder',ok:true},{t:'+ on String'},{t:'char =='},{t:'System.exit'}],explain:'One whiteboard, not copies.'}],takeaways:['Strings never mutate.','Use the returned new string.','Loops → StringBuilder.'],recall:'What happens to the original in s + "!"?',todo:'Find one ignored string result in old code; fix.',anim:{title:'Photocopy',steps:[{caption:'Book "java" printed.',html:'<div class="pipe"><div class="box"><b>"java"</b> 📕</div></div>'},{caption:'toUpperCase photocopies.',html:'<div class="pipe"><div class="box">"java"</div><span class="arr">→</span><div class="box"><b>"JAVA"</b> 📄 new</div></div>'},{caption:'s still points to old unless reassigned.',html:'<div class="pipe"><div class="box">s → "java" (old)</div></div>'}]}},
'stringbuilder':{intro:'StringBuilder is the whiteboard for text: scribble, append, fix — then photograph (toString) when done.',question:'How do you collect 1,000 signatures without 1,000 papers?',analogy:'Whiteboard list: append one more line each time, erase a typo in place. Photograph at end for the printed book (String).',analogyFail:'Where it breaks: whiteboards are not for sharing across strangers (not thread-safe) — fine for our single-thread apps; also not == String.',explain:['<b>new StringBuilder()</b>, <b>append(x)</b> chains, <b>toString()</b> finishes. <b>length()</b>, <b>reverse()</b>, <b>delete()</b> help.','Mutable: same object grows. Perfect in loops.','Convert: String done = sb.toString(); Compare via toString().equals().'],code:`StringBuilder sb = new StringBuilder();\nfor (int i = 1; i <= 3; i++) sb.append(i).append(" ");\nSystem.out.println(sb.toString()); // "1 2 3 "\nSystem.out.println(sb.reverse().toString());`,codeNotes:['One object, 3 appends.','toString snapshots.','reverse edits in place!'],output:'1 2 3 \n 3 2 1',why:'Appends mutate the same builder; reverse flips it.',sim:{kind:'concat',label:'Append pieces to the board.',fields:[{v:'1 2 '},{v:'3'}]},mistakes:[{bad:'String s = sb; (type mismatch)',why:'Builder ≠ String.',fix:'String s = sb.toString();'},{bad:'+ in big loop still',why:'Copies each round.',fix:'Append to one builder.'},{bad:'Forgetting toString for equals',why:'Builder equals is identity.',fix:'sb.toString().equals("...")'}],practices:[{title:'CSV line',task:'Build "a,b,c," from 1..3 with builder.',hint:'append(i).append(",").',sol:'Loop appends → toString.'},{title:'Fix loop',task:'Rewrite loop s += w with builder.',hint:'One sb outside.',sol:'StringBuilder sb = new...; loop sb.append(w);'}],quiz:[{id:'q1',prompt:'Finish builder to String via…',options:[{t:'toString()',ok:true},{t:'equals()'},{t:'append()'},{t:'new String'}],explain:'Snapshot photo.'},{id:'q2',prompt:'append in loop edits…',options:[{t:'Same object (mutable)',ok:true},{t:'A copy each time'},{t:'Nothing'},{t:'The console'}],explain:'Whiteboard grows.'},{id:'q3',prompt:'Builder vs String + in loops?',options:[{t:'Builder faster, less garbage',ok:true},{t:'+ faster'},{t:'Same'},{t:'Neither works'}],explain:'One board vs copies.'}],takeaways:['Builder = mutable text board.','append chains; toString finishes.','Default for loop-built text.'],recall:'When must you pick Builder over +?',todo:'Rewrite one loop-concat with Builder.',anim:{title:'Whiteboard',steps:[{caption:'Empty board.',html:'<div class="pipe"><div class="box">board: ""</div></div>'},{caption:'Append 1, 2, 3 in place.',html:'<div class="pipe"><div class="box">board: "1 2 3 " ✏️</div></div>'},{caption:'Photograph → String.',html:'<div class="pipe"><div class="box">toString → "1 2 3 " 📸</div></div>'}]}},
'algorithms-basic':{intro:'Four tiny superpowers: find biggest, count matches, search an item, track minimum. Same loop skeleton, different memory.',question:'How do you find the tallest student in a line without measuring twice?',analogy:'Trophy walk: hold current champion (best so far), walk the line, swap when taller appears. Counting = clicker per match. Searching = stop at first name match.',analogyFail:'Where it breaks: empty line has no champion — guard empty arrays or crash on a[0].',explain:['<b>Max/min</b>: best = a[0]; loop rest, update. <b>Count</b>: c=0, c++ on match.','<b>Linear search</b>: return index or -1. Stop early with break/return.','Init matters: max to first (not 0, negatives!), count to 0.'],code:`int[] a = {4, 9, 2, 9};\nint max = a[0], count9 = 0, pos2 = -1;\nfor (int i = 0; i < a.length; i++) {\n  if (a[i] > max) max = a[i];\n  if (a[i] == 9) count9++;\n  if (a[i] == 2) pos2 = i;\n}\nSystem.out.println(max + " " + count9 + " " + pos2);`,codeNotes:['Champion starts at first.','Each slot tested once.','Results: 9, two 9s, 2 at index 2.'],output:'9 2 2',why:'One walk collects three answers — same skeleton, different notes.',sim:{kind:'array',label:'Search doors 0-3.',fields:[{v:'2'}]},mistakes:[{bad:'max = 0 with negatives',why:'0 beats -5 wrongly.',fix:'max = a[0].'},{bad:'Empty array a[0]',why:'No champion — crash.',fix:'if (a.length == 0) handle.'},{bad:'Forgetting -1 for missing',why:'0 looks like found at 0.',fix:'Init -1, set on found.'}],practices:[{title:'Min it',task:'Min of {4,9,2,9}.',hint:'Mirror max with <.',sol:'2.'},{title:'Count evens',task:'Count evens in array.',hint:'% 2 == 0 → c++.',sol:'Loop + counter.'}],quiz:[{id:'q1',prompt:'Max init for unknown values?',options:[{t:'a[0]',ok:true},{t:'0 always'},{t:'999999'},{t:'-1'}],explain:'First real contender.'},{id:'q2',prompt:'Search missing returns?',options:[{t:'-1',ok:true},{t:'0'},{t:'null'},{t:'length'}],explain:'-1 = absent.'},{id:'q3',prompt:'Output above?',options:[{t:'9 2 2',ok:true},{t:'4 1 0'},{t:'9 1 2'},{t:'2 2 9'}],explain:'Max 9, two 9s, 2 at 2.'}],takeaways:['One loop, many answers.','Init champion to first; missing = -1.','Guard empty arrays.'],recall:'What three inits for max/count/search?',todo:'Find min + count of 5 in your ages.',anim:{title:'Trophy walk',steps:[{caption:'Champion = 4 (first).',html:'<div class="viz"><div class="varbox"><div class="nm">🏆 max</div><div class="vl">4</div></div></div>'},{caption:'See 9 → swap champion!',html:'<div class="viz"><div class="varbox"><div class="nm">🏆 max</div><div class="vl">9 ✨</div></div></div>'},{caption:'2, 9: count 9s = 2, done.',html:'<div class="viz"><div class="varbox"><div class="nm">count9</div><div class="vl">2</div></div></div>'}]}},
};
